// SYNTHETIC learning fixture (not production code).
import java.util.Map;

public class PluginLoader {
    private static final Map<String, Class<?>> PLUGINS = Map.of("csv", CsvPlugin.class, "json", JsonPlugin.class);

    public Object load(String name) throws Exception {
        Class<?> type = PLUGINS.get(name);
        if (type == null) {
            throw new IllegalArgumentException("unknown plugin");
        }
        return type.getDeclaredConstructor().newInstance();
    }
}
